from pathlib import Path
import json
families = [
 dict(id='relationship', name='Relationship humour', headline="Keep the couch. Keep the friends.", support="Moving is stressful enough. Your couch shouldn't cost you a friendship.", visual='Two offset abstract speech bubbles around a sculptural sofa. Warm peach, deep green and plenty of open space.', color='#eedaca', shape='sofa', variants=[('Very short','Keep the couch. Keep the friends. Get a free moving quote.'),('Funny',"Your friendship has survived a lot. That third-floor couch might be asking too much. Let’s talk about your move."),('Professional','Planning a local home move? Tell IWantToMove.ca where you’re going and request a free quote.'),('Stress relief',"You can invite your friends over once the couch is in. Start with a free moving quote.")]),
 dict(id='friend-with-a-truck', name='Friend with a truck', headline="A truck isn't a moving plan.", support='Give your friend the day off. Ask us about your move.', visual='Large geometric truck silhouette, a single box and a generous cream field. No borrowed manufacturer marks.', color='#e5e7cf', shape='truck', variants=[('Very short','Your friend has a truck. We have a quote form. Start there.'),('Funny',"‘I know someone with a truck’ is how a lot of very long Saturdays begin. Get a free moving quote."),('Professional','Looking at options for your local move? Share the details and we’ll talk through a quote.'),('Convenience',"Before you coordinate five friends and a borrowed truck, tell us what needs to move.")]),
 dict(id='moving-stress', name='Moving stress', headline='One less thing on your moving list.', support='Tell us where you’re headed. Start with a free quote.', visual='An oversized paper list with abstract strokes and one bold check. No extra readable copy inside the illustration.', color='#dfe6d8', shape='list', variants=[('Very short','Moving list getting longer? Start with a free quote.'),('Funny',"You’ve packed the kettle. You need the kettle. Moving is a lot. Let’s sort out the moving quote."),('Professional','Request a free quote for local residential or office moving. We’ll call to confirm the details.'),('Urgency',"Moving date getting closer? Tell us when you’re hoping to move. We’ll discuss your request and availability.")]),
 dict(id='couch', name='Couch and furniture', headline='Big couch. New address.', support='Let’s talk about getting it there as part of your move.', visual='An architectural green sofa across a terracotta doorway. Dimensional shadows, no stock photos or service claims.', color='#e8c5ae', shape='sofa', variants=[('Very short','Big couch. New address. Get a quote for your home move.'),('Funny',"It looked smaller in the showroom. Tell us about the couch, the stairs and the rest of your move."),('Professional','Moving home? Include larger furniture and building access in your quote request so we can discuss the details.'),('Stress relief',"You don’t have to work out every detail before asking. Tell us about your home move and we’ll start there.")]),
 dict(id='professional', name='Straightforward professional control', headline='Your next move starts here.', support='Local residential and office moving. Ask for a free quote.', visual='Precise typography with a large directional arrow and two dimensional boxes. Deep forest field, pale lime accents.', color='#193f35', shape='boxes', variants=[('Very short','Local home and office moving. Get a free quote.'),('Professional','Tell IWantToMove.ca where you’re moving, your preferred date and what needs to come with you. We’ll contact you to discuss a quote.'),('Trust',"A moving quote should start with the details. Let’s go over yours before you decide."),('Convenience','Share your move details in our short form. We’ll call to go over the next steps.')]),
 dict(id='stairs', name='Stairs and elevators', headline='The stairs deserve a mention.', support='Tell us about your building when you ask for a moving quote.', visual='Five broad architectural steps, a box on a landing and a subtle diagonal shadow. Muted yellow with green type.', color='#ebe1b8', shape='stairs', variants=[('Very short','New place. Different stairs. Get a free moving quote.'),('Funny',"‘Just a few stairs’ is doing a lot of work in that sentence. Tell us about your building and your move."),('Professional','Planning a local move? Include stairs, elevators and building access in your request so we can go over the details.'),('Urgency',"Have a moving date in mind? Check your building’s elevator booking rules, then tell us about your move.")]),
]
Path('marketing/creatives/families.json').write_text(json.dumps(families, indent=2)+'\n')
concepts = '# Creative families\n\nSix concepts for testing. The professional family is the control. All are draft creative directions; they make no claims about capacity, price, insurance or availability.\n\n'
copy = '# Ad copy\n\nUse one primary text and one headline per ad. Keep the professional control live while rotating challengers. Availability is always confirmed in conversation; urgency copy does not imply limited slots.\n\n'
for f in families:
 concepts += f"## {f['name']}\n\nConcept: {f['visual']}\n\nHeadline: {f['headline']}\n\nSupporting line: {f['support']}\n\nCTA: Get a Free Moving Quote → /quote.\n\nFormats: 4:5 feed and 9:16 Stories/Reels static placement. HTML: creatives/{f['id']}.html?ratio=45 or ?ratio=916.\n\n"
 copy += f"## {f['name']}\n\n" + ''.join(f"- {kind}: {text}\n" for kind,text in f['variants']) + '\n'
headlines=['Get a Free Moving Quote','Keep the Couch. Keep the Friends.','Your Next Move Starts Here','Big Couch. New Address.','Moving Home? Start Here.','A New Space for Your Office','One Less Thing on Your List','Tell Us About Your Move','The Stairs Deserve a Mention','Give Your Friend the Day Off']
descriptions=['Local home and office moving','Tell us where you’re headed','Start with a free quote','Let’s talk about your move','A few details. Then a call.','Call 778-513-7503']
copy += '## Headlines (40 characters maximum)\n\n' + ''.join(f'- {h} ({len(h)})\n' for h in headlines)
copy += '\n## Descriptions (30 characters maximum)\n\n' + ''.join(f'- {d} ({len(d)})\n' for d in descriptions)
copy += '\n## Instant Form copy\n\nHeadline: Get a Free Moving Quote\n\nIntro: Tell us a little about your move. We’ll call to confirm the details and give you a quote.\n\nContact permission: By sending this request, you’re asking IWantToMove.ca to contact you about your move.\n\nReview prompt: Please check your phone number and move details before sending.\n\nThank-you headline: Thanks. Your request is in.\n\nThank-you body: We’ll review your move and call within [[PLACEHOLDER: response time]] to confirm the details and give you a quote. Your move isn’t booked yet. You can also call 778-513-7503.\n\nButton: View next steps → https://iwantomove.ca/thank-you\n\nThe complete field specification and privacy link are in 01-campaign-structure.md.\n'
Path('marketing/02-creative-families.md').write_text(concepts.rstrip()+'\n')
Path('marketing/03-ad-copy.md').write_text(copy)
for f in families:
 dark=f['id']=='professional'
